    "type": "module"
  },
  "action": {
    "default_title": "Open Roblox In Browser"
  }
}

// Background service worker: opens the client page in a tab.
chrome.action.onClicked.addListener(() => {
  chrome.tabs.create({ url: chrome.runtime.getURL('src/client.html') });
});

// RbxTransport wire-format codecs, reconstructed from the Roblox client binaries.
//
// Layers (outermost first):
//   QUIC / HTTP3 + WebTransport (handled by the browser)
//     -> application channels (reliable = bidi stream, unreliable = datagram)
//          reliable stream header:  [0x06][0x01][appIndex:u8][channelId:u32 BE]
//          reliable message frame:  QUIC varint(length) + payload
//          unreliable datagram:     varint(zigzag channelId) varint(sendId) varint(fragSize) [varint(frag)] payload
//          control messages (app="ctrl", channel 0):
//             OpenReliableChannelControl:   [type=1][appIndex:u8][channelId:u8][streamId:u32 BE]
//             OpenUnreliableChannelControl: [type=2][appIndex:u8][channelId:u8][streamId:u32 BE][wireId:u32 BE]
//             CloseUnreliableChannelControl:[type=3][reason:u8][wireId:varint][channelId:varint]
//
// The RUPP prefix layer sits below QUIC (it is prepended to UDP packets) and is
// intentionally NOT implemented here: production runs with
// RbxTransportPureQuicSupport=true, and the server auto-detects raw QUIC by the
// fixed bit 0x40. A browser can only emit raw QUIC, which is exactly that case.

export const CTRL_APP_ID = 0x6374726c; // "ctrl"

export class Reader {
  constructor(bytes, offset = 0) {
    this.bytes = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    this.offset = offset;
  }
  get remaining() { return this.bytes.length - this.offset; }
  u8() {
    if (this.remaining < 1) throw new RangeError('reader underflow (u8)');
    return this.bytes[this.offset++];
  }
  u16be() {
    if (this.remaining < 2) throw new RangeError('reader underflow (u16)');
    const v = (this.bytes[this.offset] << 8) | this.bytes[this.offset + 1];
    this.offset += 2;
    return v;
  }
  u32be() {
    if (this.remaining < 4) throw new RangeError('reader underflow (u32)');
    const b = this.bytes, o = this.offset;
    const v = ((b[o] * 0x1000000) + ((b[o + 1] << 16) | (b[o + 2] << 8) | b[o + 3])) >>> 0;
    this.offset += 4;
    return v;
  }
  u64be() {
    if (this.remaining < 8) throw new RangeError('reader underflow (u64)');
    const hi = this.u32be(), lo = this.u32be();
    return (BigInt(hi) << 32n) | BigInt(lo);
  }
  bytesN(n) {
    if (this.remaining < n) throw new RangeError('reader underflow (bytes)');
    const out = this.bytes.subarray(this.offset, this.offset + n);
    this.offset += n;
    return out;
  }
  // RFC 9000 QUIC variable-length integer.
  varint() {
    if (this.remaining < 1) throw new RangeError('reader underflow (varint)');
    const first = this.bytes[this.offset];
    const len = 1 << (first >> 6);
    if (this.remaining < len) throw new RangeError('reader underflow (varint body)');
    return { value: this.readVarintRaw(), len };
  }
  readVarintRaw() {
    const first = this.bytes[this.offset];
    const len = 1 << (first >> 6);
    let v = BigInt(first & 0x3f);
    for (let i = 1; i < len; i++) v = (v << 8n) | BigInt(this.bytes[this.offset + i]);
    this.offset += len;
    return v;
  }
  // Zigzag-decoded varint (signed).
  svarint() {
    const { value } = this.varint();
    const sign = (value & 1n) === 1n;
    const mag = value >> 1n;
    return sign ? -mag : mag;
  }
}

export class Writer {
  constructor() { this.buf = new Uint8Array(256); this.len = 0; }
  ensure(extra) {
    if (this.len + extra <= this.buf.length) return;
    let cap = this.buf.length * 2;
    while (cap < this.len + extra) cap *= 2;
    const nb = new Uint8Array(cap);
    nb.set(this.buf.subarray(0, this.len));
    this.buf = nb;
  }
  u8(v) { this.ensure(1); this.buf[this.len++] = v & 0xff; return this; }
  u16be(v) { this.ensure(2); this.buf[this.len++] = (v >> 8) & 0xff; this.buf[this.len++] = v & 0xff; return this; }
  u32be(v) {
    this.ensure(4);
    this.buf[this.len++] = (v >>> 24) & 0xff;
    this.buf[this.len++] = (v >>> 16) & 0xff;
    this.buf[this.len++] = (v >>> 8) & 0xff;
    this.buf[this.len++] = v & 0xff;
    return this;
  }
  bytes(arr) { this.ensure(arr.length); this.buf.set(arr, this.len); this.len += arr.length; return this; }
  // RFC 9000 QUIC varint.
  varint(v) {
    v = BigInt(v);
    if (v < 0n) throw new RangeError('varint must be non-negative');
    let len;
    if (v <= 0x3fn) len = 1;
    else if (v <= 0x3fffn) len = 2;
    else if (v <= 0x3fffffffn) len = 4;
    else if (v <= 0x3fffffffffffffffn) len = 8;
    else throw new RangeError('varint too large');
    this.ensure(len);
    const o = this.len;
    for (let i = len - 1; i >= 0; i--) { this.buf[o + i] = Number(v & 0xffn); v >>= 8n; }
    this.buf[o] |= (len === 1 ? 0 : len === 2 ? 0x40 : len === 4 ? 0x80 : 0xc0);
    this.len += len;
    return this;
  }
  svarint(v) {
    v = BigInt(v);
    const zz = v >= 0n ? (v << 1n) : ((-v << 1n) - 1n);
    return this.varint(zz);
  }
  toBytes() { return this.buf.slice(0, this.len); }
}

export function varintSize(v) {
  v = BigInt(v);
  if (v <= 0x3fn) return 1;
  if (v <= 0x3fffn) return 2;
  if (v <= 0x3fffffffn) return 4;
  return 8;
}

export function concatBytes(...chunks) {
  let total = 0;
  for (const c of chunks) total += c.length;
  const out = new Uint8Array(total);
  let o = 0;
  for (const c of chunks) { out.set(c, o); o += c.length; }
  return out;
}

// ---------------------------------------------------------------------------
// Reliable stream header
// ---------------------------------------------------------------------------
export const STREAM_HEADER_MAGIC = 0x06;

export function encodeStreamHeader(appIndex, channelId) {
  return new Writer().u8(STREAM_HEADER_MAGIC).u8(0x01).u8(appIndex).u32be(channelId).toBytes();
}

export function decodeStreamHeader(bytes) {
  const r = new Reader(bytes);
  const magic = r.u8();
  const kind = r.u8();
  const appIndex = r.u8();
  const channelId = r.u32be();
  return { magic, kind, appIndex, channelId, headerLen: r.offset };
}

// ---------------------------------------------------------------------------
// Reliable message framing (QUIC varint length prefix)
// ---------------------------------------------------------------------------
export function frameMessage(payload) {
  return concatBytes(new Writer().varint(payload.length).toBytes(), payload);
}

// ---------------------------------------------------------------------------
// Unreliable datagram header
// ---------------------------------------------------------------------------
export function encodeDatagramHeader(channelIdSigned, sendId, fragSize = 0, frag = 0) {
  const w = new Writer().svarint(channelIdSigned).varint(sendId).varint(fragSize);
  if (fragSize !== 0) w.varint(frag);
  return w.toBytes();
}

export function decodeDatagramHeader(bytes) {
  const r = new Reader(bytes);
  const channelIdSigned = r.svarint();
  const sendId = r.varint().value;
  const fragSize = r.varint().value;
  let frag = 0n;
  if (fragSize !== 0n) frag = r.varint().value;
  return { channelIdSigned, sendId: BigInt(sendId), fragSize, frag, headerLen: r.offset };
}

// ---------------------------------------------------------------------------
// Control-channel messages
// ---------------------------------------------------------------------------
export const CtrlMsg = Object.freeze({
  OpenReliable: 1,
  OpenUnreliable: 2,
  CloseUnreliable: 3,
  Handshake: 4,
  AppControl: 5,
  FlowControl: 6,
  Ack: 7,
  Loss: 8,
  AppFin: 9,
  ConnClose: 10,
  StreamClose: 11,
  StreamAccepted: 12,
  NewAppConnection: 13,
  AcceptConnection: 14,
  AcceptH3: 15,
  AcceptWtSession: 16,
});

export const CtrlMsgName = Object.fromEntries(Object.entries(CtrlMsg).map(([k, v]) => [v, k]));

export function encodeOpenReliable(appIndex, channelId) {
  return new Writer().u8(CtrlMsg.OpenReliable).u8(appIndex).u8(channelId).u32be(0).toBytes();
}

export function encodeOpenUnreliable(appIndex, channelId, wireId = 0) {
  return new Writer().u8(CtrlMsg.OpenUnreliable).u8(appIndex).u8(channelId).u32be(0).u32be(wireId).toBytes();
}

export function encodeCloseUnreliable(reason, wireId, channelId) {
  return new Writer().u8(CtrlMsg.CloseUnreliable).u8(reason).varint(wireId).varint(channelId).toBytes();
}

export function decodeCtrlMessage(bytes) {
  const r = new Reader(bytes);
  const type = r.u8();
  const out = { type, name: CtrlMsgName[type] ?? `Unknown(${type})` };
  try {
    switch (type) {
      case CtrlMsg.OpenReliable: {
        out.appIndex = r.u8();
        out.channelId = r.u8();
        out.streamId = r.u32be();
        break;
      }
      case CtrlMsg.OpenUnreliable: {
        out.appIndex = r.u8();
        out.channelId = r.u8();
        out.streamId = r.u32be();
        out.wireId = r.u32be();
        break;
      }
      case CtrlMsg.CloseUnreliable: {
        out.reason = r.u8();
        out.wireId = r.varint().value;
        out.channelId = r.varint().value;
        break;
      }
      default:
        out.raw = bytes;
        break;
    }
  } catch (e) {
    out.error = String(e);
  }
  return out;
}

// ---------------------------------------------------------------------------
// Utility
// ---------------------------------------------------------------------------
export function toHex(bytes, sep = ' ') {
  return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join(sep);
}

// Roblox GameJoin flow, reconstructed from GameJoinUtil / PlayerConfigurer.
//
// v1: POST https://gamejoin.roblox.com/v1/join-game
// v2: POST https://gamejoin.roblox.com/v2/join-game   (reactive GameJoinV2)
//
// All requests use credentials: "include" so the browser attaches the user's
// session cookies (.ROBLOSECURITY). Roblox POST endpoints are CSRF-protected:
// a 403 response carries an "x-csrf-token" header that must be echoed back.

const GAMEJOIN = 'https://gamejoin.roblox.com';
const AUTHED_USER = 'https://users.roblox.com/v1/users/authenticated';

export class RobloxApiError extends Error {
  constructor(message, { status, body, url } = {}) {
    super(message);
    this.name = 'RobloxApiError';
    this.status = status;
    this.body = body;
    this.url = url;
  }
}

function uuid() {
  return crypto.randomUUID();
}

export async function getAuthenticatedUser(log = () => {}) {
  log('GET ' + AUTHED_USER + ' (credentials: include)');
  const res = await fetch(AUTHED_USER, { credentials: 'include' });
  if (res.status === 401 || res.status === 403) {
    const text = await res.text().catch(() => '');
    throw new RobloxApiError('Not logged in to Roblox (no valid .ROBLOSECURITY cookie).', {
      status: res.status, body: text, url: AUTHED_USER,
    });
  }
  if (!res.ok) {
    throw new RobloxApiError(`Unexpected status ${res.status} from users API`, { status: res.status, url: AUTHED_USER });
  }
  const user = await res.json();
  log(`Authenticated as ${user.name} (id ${user.id})`);
  return user;
}

async function postJson(url, body, log) {
  const doFetch = (csrf) => fetch(url, {
    method: 'POST',
    credentials: 'include',
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}),
    },
    body: JSON.stringify(body),
  });

  let res = await doFetch(null);
  if (res.status === 403) {
    const csrf = res.headers.get('x-csrf-token');
    if (csrf) {
      log(`Got CSRF challenge, retrying with token`);
      res = await doFetch(csrf);
    }
  }
  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { /* keep raw text */ }
  return { res, json, text };
}

export function buildJoinBody({ placeId, universeId, jobId, eventId, launchData, joinAttemptOrigin }) {
  const body = {
    placeId: Number(placeId),
    isTeleport: false,
    gameJoinAttemptId: uuid(),
    browserTrackerId: 0,
    playSessionId: uuid(),
    eventId: eventId || uuid(),
    launchData: launchData || '',
    joinAttemptOrigin: joinAttemptOrigin || 'PlayButton',
  };
  if (universeId) body.gameId = Number(universeId);
  if (jobId) body.jobId = jobId;
  return body;
}

/**
 * Calls the game-join API. Tries v1 (default client path) first and falls back
 * to v2 (reactive GameJoinV2) when the server rejects v1 or the account is in
 * the v2 rollout.
 */
export async function joinGame(params, log = () => {}) {
  const body = buildJoinBody(params);
  const attempts = [
    { path: '/v1/join-game', label: 'v1' },
    { path: '/v2/join-game', label: 'v2' },
  ];
  let last = null;
  for (const attempt of attempts) {
    const url = GAMEJOIN + attempt.path;
    log(`POST ${url}\n  body: ${JSON.stringify(body)}`);
    const { res, json, text } = await postJson(url, body, log);
    log(`<- HTTP ${res.status} (${text.length} bytes)`);
    if (res.ok && json) {
      return { api: attempt.label, url, status: res.status, response: json };
    }
    last = new RobloxApiError(`join-game ${attempt.label} failed with HTTP ${res.status}`, {
      status: res.status, body: text, url,
    });
    // Only fall through to the next version on auth/availability style errors.
    if (![400, 403, 404, 405, 426].includes(res.status)) break;
  }
  throw last ?? new RobloxApiError('join-game failed');
}

/**
 * Extracts the joinScript payload. Handles both the direct object and the
 * nested {"status":2,"joinScript":{...}} envelope.
 */
export function extractJoinScript(joinResponse) {
  if (!joinResponse) return null;
  if (joinResponse.joinScript && typeof joinResponse.joinScript === 'object') return joinResponse.joinScript;
  if (joinResponse.JoinScript && typeof joinResponse.JoinScript === 'object') return joinResponse.JoinScript;
  return joinResponse;
}

function tryParseJson(value) {
  if (typeof value !== 'string') return value;
  const t = value.trim();
  if (!t.startsWith('{') && !t.startsWith('[')) return value;
  try { return JSON.parse(t); } catch { return value; }
}

function pick(obj, ...names) {
  if (!obj || typeof obj !== 'object') return undefined;
  for (const n of names) {
    if (obj[n] !== undefined && obj[n] !== null) return obj[n];
  }
  const lower = new Map(Object.keys(obj).map(k => [k.toLowerCase(), k]));
  for (const n of names) {
    const k = lower.get(n.toLowerCase());
    if (k !== undefined && obj[k] !== undefined && obj[k] !== null) return obj[k];
  }
  return undefined;
}

/**
 * Normalizes the join reply into the fields needed for the WebTransport leg.
 * Field names are matched case-insensitively across the plausible spellings
 * observed in the client (GameFqdn/gameFqdn, NetStackPort, ServerPort, ...).
 */
export function extractTransportInfo(joinResponse, log = () => {}) {
  const js = extractJoinScript(joinResponse);
  if (!js || typeof js !== 'object') {
    throw new Error('join reply contained no joinScript object');
  }
  log('joinScript keys: ' + Object.keys(js).join(', '));

  const consumed = new Set();

  // --- host / port -------------------------------------------------------
  let fqdn = pick(js, 'GameFqdn', 'gameFqdn', 'GameFQDN', 'gameFqdnHost');
  let netStackPort = pick(js, 'NetStackPort', 'netStackPort');
  let serverPort = pick(js, 'ServerPort', 'serverPort');
  let clientPort = pick(js, 'ClientPort', 'clientPort');
  let serverConnections = pick(js, 'ServerConnections', 'serverConnections');
  let udmuxEndpoints = pick(js, 'UdmuxEndpoints', 'udmuxEndpoints');
  let dsr = pick(js, 'DirectServerReturn', 'directServerReturn');

  // Some builds nest transport data in RbxTransportConfig / NetStackConfig.
  const rbxConfigRaw = pick(js, 'RbxTransportConfig', 'rbxTransportConfig');
  const rbxConfig = tryParseJson(rbxConfigRaw) || {};
  const netStackRaw = pick(js, 'NetStackConfig', 'netStackConfig');
  const netStack = tryParseJson(netStackRaw) || {};
  if (typeof rbxConfig === 'object') log('RbxTransportConfig keys: ' + Object.keys(rbxConfig).join(', '));
  if (typeof netStack === 'object') log('NetStackConfig keys: ' + Object.keys(netStack).join(', '));

  fqdn = fqdn ?? pick(rbxConfig, 'fqdn', 'host', 'ip') ?? pick(netStack, 'host', 'ip');
  netStackPort = netStackPort ?? pick(netStack, 'port');
  serverConnections = serverConnections ?? pick(rbxConfig, 'ServerConnections');

  const endpointFromList = (list) => {
    if (!Array.isArray(list) || !list.length) return null;
    const first = list[0];
    if (typeof first === 'string') {
      const m = first.match(/^(.*?):(\d+)$/);
      if (m) return { host: m[1], port: Number(m[2]) };
      return { host: first, port: null };
    }
    if (first && typeof first === 'object') {
      const host = pick(first, 'Address', 'address', 'Ip', 'ip', 'Host', 'host', 'Endpoint', 'endpoint');
      const port = pick(first, 'Port', 'port');
      if (host) {
        const m = String(host).match(/^(.*?):(\d+)$/);
        if (m) return { host: m[1], port: port != null ? Number(port) : Number(m[2]) };
        return { host, port: port != null ? Number(port) : null };
      }
    }
    return null;
  };

  const fromServerConns = endpointFromList(serverConnections);
  const fromUdmux = endpointFromList(udmuxEndpoints);
  if (!fqdn && fromServerConns) { fqdn = fromServerConns.host; netStackPort ??= fromServerConns.port; }
  if (!fqdn && fromUdmux) { fqdn = fromUdmux.host; netStackPort ??= fromUdmux.port; }

  if (!fqdn) throw new Error('join reply has no GameFqdn / server address');
  if (!netStackPort) {
    if (serverPort) {
      log('warning: NetStackPort missing; falling back to ServerPort (likely RakNet, not WT)');
      netStackPort = serverPort;
    } else {
      throw new Error('join reply has no NetStackPort');
    }
  }

  // --- capabilities ------------------------------------------------------
  // The client takes the u64 capability mask from RbxTransportConfig.
  // The wire value is 16 lowercase hex, so any numeric/hex/binary form here
  // is normalized.
  let capsRaw = pick(rbxConfig, 'serverCapabilities', 'ServerCapabilities', 'capabilities', 'caps')
    ?? pick(netStack, 'caps', 'capabilities')
    ?? pick(js, 'ServerCapabilities', 'serverCapabilities');

  let capsHex = null;
  if (capsRaw !== undefined) {
    capsHex = normalizeCaps(capsRaw, log);
  } else {
    log('warning: no capabilities found in join reply; sending 0000000000000000');
    capsHex = '0000000000000000';
  }

  // --- certificate hashes ------------------------------------------------
  // NetStackConfig.certHashes: SHA-256 digests of the server's WebTransport
  // certificate, used for browser-style certificate pinning.
  let certHashesRaw = pick(netStack, 'certHashes', 'CertHashes', 'certificateHashes')
    ?? pick(rbxConfig, 'certHashes', 'CertHashes');
  const certHashes = normalizeCertHashes(certHashesRaw, log);

  const info = {
    joinScript: js,
    fqdn,
    netStackPort: Number(netStackPort),
    serverPort: serverPort != null ? Number(serverPort) : null,
    clientPort: clientPort != null ? Number(clientPort) : null,
    serverConnections,
    udmuxEndpoints,
    directServerReturn: !!dsr,
    capsHex,
    capsRaw,
    certHashes,
    rbxTransportConfig: typeof rbxConfig === 'object' ? rbxConfig : null,
    netStackConfig: typeof netStack === 'object' ? netStack : null,
  };
  void consumed;
  return info;
}

export function normalizeCaps(value, log = () => {}) {
  try {
    let big;
    if (typeof value === 'number') {
      if (!Number.isSafeInteger(value)) log('caps is a large number; precision may be lossy');
      big = BigInt(Math.trunc(value));
    } else if (typeof value === 'bigint') {
      big = value;
    } else if (typeof value === 'string') {
      const t = value.trim();
      if (t === '') return '0000000000000000';
      if (/^0x[0-9a-f]+$/i.test(t)) big = BigInt(t);
      else if (/^[0-9a-f]{16}$/i.test(t)) big = BigInt('0x' + t);
      else if (/^\d+$/.test(t)) big = BigInt(t);
      else if (/^[0-9a-f]+$/i.test(t)) big = BigInt('0x' + t);
      else throw new Error(`unrecognized caps format: ${t}`);
    } else {
      throw new Error('unrecognized caps type: ' + typeof value);
    }
    const hex = (big & 0xffffffffffffffffn).toString(16).padStart(16, '0');
    log(`capabilities = 0x${hex} (from ${JSON.stringify(value)})`);
    return hex;
  } catch (e) {
    log('warning: failed to parse capabilities: ' + e.message);
    return '0000000000000000';
  }
}

export function normalizeCertHashes(value, log = () => {}) {
  if (value === undefined || value === null) return [];
  const list = Array.isArray(value) ? value : [value];
  const out = [];
  for (const item of list) {
    if (item == null) continue;
    if (item instanceof ArrayBuffer) { out.push(new Uint8Array(item)); continue; }
    if (ArrayBuffer.isView(item)) { out.push(new Uint8Array(item.buffer, item.byteOffset, item.byteLength)); continue; }
    if (typeof item !== 'string') continue;
    const t = item.trim();
    let bytes = null;
    if (/^[0-9a-f]{64}$/i.test(t)) {
      bytes = hexToBytes(t);
    } else if (/^[A-Za-z0-9+/]{43}=?$/.test(t)) {
      bytes = base64ToBytes(t);
    } else if (/^[0-9a-f]{40}$/i.test(t)) {
      continue; // SHA-1 - not usable for certificate pinning
    }
    if (bytes && bytes.length === 32) out.push(bytes);
  }
  log(`certHashes: ${out.length} SHA-256 digest(s)` + (out.length === 0 ? ' (none usable -> TLS pinning disabled)' : ''));
  return out;
}

export function hexToBytes(hex) {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

export function base64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// WebTransport connection to a Roblox game server (RtcIo/RbxTransport over WT).
//
// Establishes:  https://<GameFqdn>:<NetStackPort>/wt?X-Rbx-Capabilities=<16hex>
// Per the binary, the server's capability extractor checks the
// X-Rbx-Capabilities *header* first and then falls back to the query string.
// Browsers cannot set custom headers on the extended CONNECT request, so the
// query form is used exclusively here.
//
// After the session is up, the client opens channel 0 of the "ctrl"
// application on a reliable bidi stream:
//   [0x06][0x01][appIndex:u8][channelId:u32 BE]
// and exchanges control messages.

import {
  CtrlMsg, CtrlMsgName, Reader, Writer,
  decodeCtrlMessage, decodeDatagramHeader, decodeStreamHeader,
  encodeOpenReliable, encodeStreamHeader, frameMessage, toHex,
} from './protocol.js';

export class RbxTransportClient extends EventTarget {
  constructor({ certHashes = [], ctrlAppIndex = 0, log }) {
    super();
    this.certHashes = certHashes;
    this.ctrlAppIndex = ctrlAppIndex;
    this.log = log || (() => {});
    this.transport = null;
    this.closed = false;

    this.ctrlStream = null;
    this.ctrlWriter = null;
    this.streams = new Map();     // streamId(hex) -> { stream, reader, remote, appIndex, channelId, buffer }
    this.datagramChannels = new Map(); // channelIdSigned(string) -> meta
    this.sendId = 0n;
    this.wireChannelId = 0;
    this.stats = { txBytes: 0, rxBytes: 0, txPackets: 0, rxPackets: 0, txDatagrams: 0, rxDatagrams: 0, streams: 0, messages: 0 };
    this._streamCounter = 0;
  }

  get connected() { return !!this.transport && !this.closed; }

  buildUrl(host, port, capsHex) {
    return `https://${host}:${port}/wt?X-Rbx-Capabilities=${capsHex}`;
  }

  async connect(host, port, capsHex) {
    const url = this.buildUrl(host, port, capsHex);
    this.log(`WebTransport -> ${url}`);
    if (this.certHashes.length) {
      this.log(`pinning ${this.certHashes.length} server certificate hash(es)`);
    } else {
      this.log('no certificate hashes; relying on WebPKI validation');
    }

    const options = {};
    if (this.certHashes.length) {
      options.serverCertificateHashes = this.certHashes.map((value) => ({ algorithm: 'sha-256', value }));
    }

    this.transport = new WebTransport(url, options);
    this.transport.addEventListener('close', () => {
      this.closed = true;
      this.log('WebTransport session closed');
      this.dispatchEvent(new CustomEvent('closed', { detail: { ...this.transport } }));
    });

    this.log('awaiting ready (QUIC + HTTP/3 CONNECT)...');
    await this.transport.ready;
    this.log('WebTransport session established');
    this.dispatchEvent(new CustomEvent('ready'));

    this._acceptIncomingStreams();
    this._acceptIncomingDatagrams();
    this._acceptBidirectionalStreams();

    return this;
  }

  _acceptBidirectionalStreams() {
    const incoming = this.transport.incomingBidirectionalStreams;
    if (!incoming) return;
    this._bidiReader = incoming.getReader();
    this._pumpBidi();
  }

  async _pumpBidi() {
    try {
      while (true) {
        const { value: stream, done } = await this._bidiReader.read();
        if (done) break;
        this._trackStream(stream, true);
      }
    } catch (e) {
      if (!this.closed) this.log('bidi stream accept loop ended: ' + e.message);
    }
  }

  _acceptIncomingStreams() {
    const incoming = this.transport.incomingUnidirectionalStreams;
    if (!incoming) return;
    this._uniReader = incoming.getReader();
    this._pumpUni();
  }

  async _pumpUni() {
    try {
      while (true) {
        const { value: stream, done } = await this._uniReader.read();
        if (done) break;
        this._trackStream(stream, false);
      }
    } catch (e) {
      if (!this.closed) this.log('uni stream accept loop ended: ' + e.message);
    }
  }

  _trackStream(stream, bidi) {
    this._streamCounter++;
    if (bidi && typeof stream.readable === 'undefined') {
      // Incoming bidi streams in some Chrome versions are plain streams.
      this._pumpStream(stream, null, bidi);
      return;
    }
    this.stats.streams++;
    this.stats.rxPackets++;
    this.log(`<- new ${bidi ? 'bidi' : 'uni'} stream #${this._streamCounter}`);
    this._pumpStream(stream, stream.readable ? stream.readable : stream, bidi);
  }

  async _pumpStream(stream, readable, bidi) {
    const reader = (readable || stream).getReader();
    let buffer = new Uint8Array(0);
    let header = null;
    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        this.stats.rxBytes += value.length;
        buffer = concat(buffer, value);
        // Parse the stream-open header first.
        if (!header) {
          if (buffer.length < 7) continue;
          try {
            header = decodeStreamHeader(buffer);
          } catch (e) {
            this.log('failed to parse stream header: ' + e.message);
            header = { invalid: true };
          }
          buffer = buffer.subarray(header.headerLen ?? 7);
          this.log(`<- stream header magic=0x${header.magic.toString(16)} kind=${header.kind} appIndex=${header.appIndex} channelId=${header.channelId}`);
        }
        // Then decode varint-length framed messages.
        let progressed = true;
        while (progressed && buffer.length) {
          progressed = false;
          try {
            const r = new Reader(buffer);
            const { value: len } = r.varint();
            const length = Number(len);
            if (buffer.length - r.offset >= length) {
              const msg = buffer.subarray(r.offset, r.offset + length);
              this._onStreamMessage(header, msg, stream, bidi);
              buffer = buffer.subarray(r.offset + length);
              progressed = true;
            }
          } catch { /* need more bytes */ }
        }
      }
    } catch (e) {
      if (!this.closed) this.log('stream read error: ' + e.message);
    }
    this.log(`<- stream #${this._streamCounter} closed`);
  }

  _onStreamMessage(header, payload, stream, bidi) {
    this.stats.messages++;
    this.stats.rxPackets++;
    const hex = toHex(payload.subarray(0, 64));
    this.log(`<- stream msg (app=${header?.appIndex} ch=${header?.channelId}) len=${payload.length}\n     ${hex}${payload.length > 64 ? ' ...' : ''}`);
    this.dispatchEvent(new CustomEvent('message', { detail: { header, payload, stream, bidi } }));

    if (header?.appIndex === this.ctrlAppIndex && header?.channelId === 0) {
      const decoded = decodeCtrlMessage(payload);
      this.log(`     ctrl: ${decoded.name} ${JSON.stringify(Object.fromEntries(Object.entries(decoded).filter(([k]) => !['name', 'raw'].includes(k)).map(([k, v]) => [k, typeof v === 'bigint' ? v.toString() : v])))}`);
      this.dispatchEvent(new CustomEvent('ctrl', { detail: decoded }));
    }
  }

  _acceptIncomingDatagrams() {
    if (!this.transport.datagrams) return;
    this._datagramReader = this.transport.datagrams.readable.getReader();
    this._pumpDatagrams();
  }

  async _pumpDatagrams() {
    try {
      while (true) {
        const { value, done } = await this._datagramReader.read();
        if (done) break;
        this.stats.rxDatagrams++;
        this.stats.rxPackets++;
        this.stats.rxBytes += value.length;
        try {
          const hdr = decodeDatagramHeader(value);
          const payload = value.subarray(hdr.headerLen);
          this.log(`<- datagram len=${value.length} channelId=${hdr.channelIdSigned} sendId=${hdr.sendId} fragSize=${hdr.fragSize}${hdr.fragSize ? ' frag=' + hdr.frag : ''}`);
          this.dispatchEvent(new CustomEvent('datagram', { detail: { header: hdr, payload } }));
        } catch (e) {
          this.log(`<- datagram (undecodable header) len=${value.length} hex=${toHex(value.subarray(0, 32))}`);
        }
      }
    } catch (e) {
      if (!this.closed) this.log('datagram loop ended: ' + e.message);
    }
  }

  /**
   * Opens a reliable channel on a brand-new bidi stream:
   * sends the stream-open header then the given payload framed.
   */
  async openReliableStream(appIndex, channelId) {
    this.log(`-> open reliable stream app=${appIndex} channel=${channelId}`);
    const stream = await this.transport.createBidirectionalStream();
    const writer = stream.writable.getWriter();
    const header = encodeStreamHeader(appIndex, channelId);
    await writer.write(header);
    this.stats.txBytes += header.length;
    this.stats.txPackets++;
    // Read side of our own stream (server control replies can come here).
    this._pumpStream(stream, stream.readable, true);
    return { stream, writer };
  }

  async openCtrlChannel() {
    const { stream, writer } = await this.openReliableStream(this.ctrlAppIndex, 0);
    this.ctrlStream = stream;
    this.ctrlWriter = writer;
    this.log('ctrl channel opened (appIndex=' + this.ctrlAppIndex + ', channel 0)');
    this.dispatchEvent(new CustomEvent('ctrlready'));
    return { stream, writer };
  }

  async sendCtrl(payload) {
    if (!this.ctrlWriter) throw new Error('ctrl channel not open');
    const framed = frameMessage(payload);
    await this.ctrlWriter.write(framed);
    this.stats.txBytes += framed.length;
    this.stats.txPackets++;
    this.log(`-> ctrl msg len=${payload.length} hex=${toHex(payload.subarray(0, 64))}`);
  }

  async openUnreliableChannel(appIndex, channelId) {
    const wireId = this.wireChannelId;
    this.wireChannelId++;
    const payload = new Writer()
      .u8(CtrlMsg.OpenUnreliable)
      .u8(appIndex)
      .u8(channelId)
      .u32be(0)
      .u32be(wireId)
      .toBytes();
    await this.sendCtrl(payload);
    this.log(`-> requested unreliable channel app=${appIndex} channel=${channelId} wireId=${wireId}`);
    return wireId;
  }

  async sendDatagram(channelIdSigned, payload) {
    if (!this.transport?.datagrams) throw new Error('datagrams not supported');
    const header = new Writer().svarint(channelIdSigned).varint(this.sendId++).varint(0).toBytes();
    const packet = concat(header, payload);
    await this.transport.datagrams.writable.getWriter().write(packet);
    this.stats.txDatagrams++;
    this.stats.txPackets++;
    this.stats.txBytes += packet.length;
    this.log(`-> datagram len=${packet.length} channelId=${channelIdSigned} sendId=${this.sendId - 1n}`);
  }

  async close() {
    if (this.closed) return;
    this.closed = true;
    try { this.transport?.close({ closeCode: 0, reason: 'client closing' }); } catch { /* ignore */ }
    this.log('connection closed by client');
  }
}

function concat(a, b) {
  const out = new Uint8Array(a.length + b.length);
  out.set(a, 0);
  out.set(b, a.length);
  return out;
}

export { CtrlMsg, CtrlMsgName };

:root {
  color-scheme: dark;
  --bg: #11131a;
  --panel: #191c26;
  --panel2: #202433;
  --text: #e8eaf2;
  --muted: #8b93ab;
  --accent: #4f8cff;
  --ok: #3ecf8e;
  --warn: #f5a623;
  --err: #ff5c5c;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font: 14px/1.45 system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}
header { padding: 18px 22px 6px; }
h1 { font-size: 18px; margin: 0; display: flex; align-items: center; gap: 10px; }
h2 { font-size: 14px; margin: 0 0 10px; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; }
.badge { font-size: 11px; font-weight: 500; color: var(--accent); border: 1px solid var(--accent); border-radius: 999px; padding: 2px 9px; }
main { display: grid; grid-template-columns: minmax(420px, 1fr) minmax(420px, 1fr); gap: 14px; padding: 12px 22px 24px; align-items: start; }
.panel { background: var(--panel); border: 1px solid #262b3b; border-radius: 10px; padding: 14px; }
.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 10px; }
label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--muted); }
label small { opacity: .7; }
input {
  background: var(--panel2); border: 1px solid #2c3247; color: var(--text);
  border-radius: 7px; padding: 7px 9px; font: inherit; font-size: 13px;
}
input:focus { outline: none; border-color: var(--accent); }
.actions { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0 10px; }
button {
  background: var(--panel2); color: var(--text); border: 1px solid #2c3247;
  border-radius: 7px; padding: 8px 14px; font: inherit; cursor: pointer;
}
button:hover:not(:disabled) { border-color: var(--accent); }
button:disabled { opacity: .45; cursor: default; }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; font-weight: 600; }
.status { padding: 7px 10px; border-radius: 7px; background: var(--panel2); font-size: 13px; }
.status.ok { color: var(--ok); }
.status.err { color: var(--err); }
.status.busy { color: var(--warn); }
.stats { margin-top: 8px; font: 11px/1.5 var(--mono); color: var(--muted); white-space: pre-wrap; }
.log {
  font: 11.5px/1.5 var(--mono); background: #0c0e14; border: 1px solid #222738;
  border-radius: 7px; padding: 10px; margin: 0; max-height: 420px; overflow: auto; white-space: pre-wrap; word-break: break-all;
}
.packets { max-height: 520px; overflow: auto; font: 11.5px/1.5 var(--mono); }
.pkt { border-bottom: 1px solid #222738; padding: 6px 2px; }
.pkt .t { color: var(--muted); }
.pkt .dir-in { color: var(--ok); }
.pkt .dir-out { color: var(--accent); }
details { margin-bottom: 10px; }
summary { cursor: pointer; color: var(--muted); font-size: 12px; }

// Client page controller: join -> WebTransport connect -> protocol session.
import { getAuthenticatedUser, joinGame, extractTransportInfo, normalizeCaps, hexToBytes } from './join.js';
import { RbxTransportClient } from './transport.js';
import {
  Reader, Writer, encodeStreamHeader, decodeStreamHeader, frameMessage,
  encodeOpenReliable, decodeCtrlMessage, decodeDatagramHeader, toHex,
} from './protocol.js';

const $ = (id) => document.getElementById(id);
const logEl = $('log');
const statusEl = $('status');
const statsEl = $('stats');
const packetsEl = $('packets');

let client = null;
let packetCount = 0;

function log(msg) {
  const ts = new Date().toISOString().slice(11, 23);
  logEl.textContent += `[${ts}] ${msg}\n`;
  logEl.scrollTop = logEl.scrollHeight;
}

function setStatus(text, cls = '') {
  statusEl.textContent = text;
  statusEl.className = 'status ' + cls;
}

function addPacket(dir, kind, detail) {
  packetCount++;
  if (packetCount === 1) packetsEl.innerHTML = '';
  const div = document.createElement('div');
  div.className = 'pkt';
  const dirCls = dir === 'in' ? 'dir-in' : 'dir-out';
  div.innerHTML = `<span class="t">${new Date().toISOString().slice(11, 23)}</span> <span class="${dirCls}">${dir === 'in' ? '&lt;-' : '-&gt;'}</span> <b>${kind}</b> ${escapeHtml(detail || '')}`;
  packetsEl.prepend(div);
  while (packetsEl.childElementCount > 400) packetsEl.lastElementChild.remove();
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}

function updateStats() {
  if (!client) { statsEl.textContent = ''; return; }
  const s = client.stats;
  statsEl.textContent =
    `tx: ${s.txPackets} packets / ${s.txBytes} B (${s.txDatagrams} datagrams)\n` +
    `rx: ${s.rxPackets} packets / ${s.rxBytes} B (${s.rxDatagrams} datagrams)\n` +
    `streams: ${s.streams} | messages: ${s.messages}`;
}
setInterval(updateStats, 500);

// ---------------------------------------------------------------------------
// Codec self-test: round-trips every message type we implemented.
// ---------------------------------------------------------------------------
function selfTest() {
  const results = [];
  const eq = (name, a, b) => results.push({ name, ok: a === b, a, b });

  // varint round trip
  for (const v of [0n, 63n, 64n, 16383n, 16384n, 1073741823n, 1073741824n, 4611686018427387903n]) {
    const w = new Writer().varint(v).toBytes();
    const r = new Reader(w).varint();
    eq(`varint(${v})`, r.value, v);
  }
  // zigzag
  for (const v of [0n, 1n, -1n, 12345n, -12345n]) {
    const w = new Writer().svarint(v).toBytes();
    eq(`svarint(${v})`, new Reader(w).svarint(), v);
  }
  // stream header
  {
    const b = encodeStreamHeader(3, 0x11223344);
    const d = decodeStreamHeader(b);
    eq('stream header magic', d.magic, 0x06);
    eq('stream header app', d.appIndex, 3);
    eq('stream header chan', d.channelId, 0x11223344);
  }
  // ctrl messages
  {
    const d = decodeCtrlMessage(encodeOpenReliable(2, 5));
    eq('ctrl OpenReliable type', d.type, 1);
    eq('ctrl OpenReliable app', d.appIndex, 2);
    eq('ctrl OpenReliable chan', d.channelId, 5);
  }
  // datagram header
  {
    const w = new Writer().svarint(-7).varint(42).varint(0).toBytes();
    const d = decodeDatagramHeader(w);
    eq('datagram channel', d.channelIdSigned, -7n);
    eq('datagram sendId', d.sendId, 42n);
  }
  // framing
  {
    const payload = new Uint8Array([1, 2, 3, 4, 5]);
    const framed = frameMessage(payload);
    const r = new Reader(framed);
    eq('frame len', Number(r.varint().value), 5);
    eq('frame body', r.u32be === undefined ? 0 : 1, 1);
  }

  const failed = results.filter(r => !r.ok);
  for (const r of results) {
    if (!r.ok) log(`SELFTEST FAIL ${r.name}: got ${r.a} expected ${r.b}`);
  }
  if (!failed.length) {
    log(`SELFTEST OK: ${results.length} checks passed`);
    setStatus('codec self-test passed', 'ok');
  } else {
    setStatus(`${failed.length} self-test failures (see log)`, 'err');
  }
}

// ---------------------------------------------------------------------------
// Main connection flow
// ---------------------------------------------------------------------------
async function doJoin() {
  const placeId = $('placeId').value.trim();
  if (!placeId) throw new Error('Place ID is required');
  const universeId = $('universeId').value.trim() || undefined;
  const jobId = $('jobId').value.trim() || undefined;

  setStatus('checking Roblox session...', 'busy');
  const user = await getAuthenticatedUser(log);

  setStatus('requesting join...', 'busy');
  const join = await joinGame({ placeId, universeId, jobId }, log);
  log(`join API responded via ${join.api}`);
  const info = extractTransportInfo(join.response, log);
  log(`endpoint: ${info.fqdn}:${info.netStackPort} (caps=0x${info.capsHex})`);
  return { user, join, info };
}

async function connectFlow({ connectOnly = false } = {}) {
  $('connectBtn').disabled = true;
  $('joinOnlyBtn').disabled = true;
  $('disconnectBtn').disabled = false;
  try {
    let info;
    if (connectOnly) {
      // reuse overrides only
      const host = $('hostOverride').value.trim();
      const port = Number($('portOverride').value.trim());
      if (!host || !port) throw new Error('host/port overrides are required for direct connect');
      const capsHex = normalizeCaps($('capsOverride').value.trim() || '0', log);
      const certHashes = ($('certOverride').value.trim() ? $('certOverride').value.trim().split(/[\s,]+/).filter(Boolean).map(hexToBytes) : []);
      info = { fqdn: host, netStackPort: port, capsHex, certHashes };
    } else {
      const { info: joined } = await doJoin();
      info = joined;
      if ($('capsOverride').value.trim()) info.capsHex = normalizeCaps($('capsOverride').value.trim(), log);
      if ($('hostOverride').value.trim()) info.fqdn = $('hostOverride').value.trim();
      if ($('portOverride').value.trim()) info.netStackPort = Number($('portOverride').value.trim());
      if ($('certOverride').value.trim()) {
        info.certHashes = $('certOverride').value.trim().split(/[\s,]+/).filter(Boolean).map(hexToBytes);
      }
    }

    const ctrlAppIndex = Number($('ctrlAppIndex').value) || 0;

    client = new RbxTransportClient({ certHashes: info.certHashes, ctrlAppIndex, log });

    client.addEventListener('ready', async () => {
      setStatus(`WebTransport connected to ${info.fqdn}:${info.netStackPort}`, 'ok');
      addPacket('in', 'WT_SESSION', `${info.fqdn}:${info.netStackPort}`);
      try {
        await client.openCtrlChannel();
        setStatus('ctrl channel open; session live', 'ok');
        addPacket('out', 'CTRL_OPEN', `appIndex=${ctrlAppIndex} channel=0`);
      } catch (e) {
        log('failed to open ctrl channel: ' + e.message);
        setStatus('ctrl channel failed: ' + e.message, 'err');
      }
    });

    client.addEventListener('ctrl', (ev) => {
      addPacket('in', 'CTRL:' + ev.detail.name, JSON.stringify(ev.detail, (k, v) => typeof v === 'bigint' ? v.toString() : v));
    });

    client.addEventListener('datagram', (ev) => {
      addPacket('in', 'DATAGRAM', `ch=${ev.detail.header.channelIdSigned} send=${ev.detail.header.sendId} bytes=${ev.detail.payload.length}`);
    });

    client.addEventListener('message', (ev) => {
      addPacket('in', 'STREAM_MSG', `app=${ev.detail.header?.appIndex} ch=${ev.detail.header?.channelId} len=${ev.detail.payload.length}`);
    });

    client.addEventListener('closed', () => {
      setStatus('session closed', 'err');
      $('connectBtn').disabled = false;
      $('disconnectBtn').disabled = true;
      updateStats();
    });

    await client.connect(info.fqdn, info.netStackPort, info.capsHex);
    // Give the ctrl-open a moment; then keep the page logging until closed.
  } catch (e) {
    log('ERROR: ' + (e?.stack || e));
    setStatus(String(e?.message || e), 'err');
    $('connectBtn').disabled = false;
    $('joinOnlyBtn').disabled = false;
    $('disconnectBtn').disabled = true;
  }
}

$('connectBtn').addEventListener('click', () => connectFlow({ connectOnly: false }));
$('joinOnlyBtn').addEventListener('click', async () => {
  try {
    $('joinOnlyBtn').disabled = true;
    const { info } = await doJoin();
    setStatus(`join ok: ${info.fqdn}:${info.netStackPort}`, 'ok');
  } catch (e) {
    log('ERROR: ' + (e?.stack || e));
    setStatus(String(e?.message || e), 'err');
  } finally {
    $('joinOnlyBtn').disabled = false;
  }
});
$('selftestBtn').addEventListener('click', selfTest);
$('disconnectBtn').addEventListener('click', async () => {
  await client?.close();
  $('disconnectBtn').disabled = true;
  $('connectBtn').disabled = false;
  $('joinOnlyBtn').disabled = false;
});
$('clearBtn').addEventListener('click', () => {
  logEl.textContent = '';
  packetsEl.innerHTML = '<em>No packets yet.</em>';
  packetCount = 0;
});

log('Roblox In Browser client ready.');
log('Extension origin: ' + location.origin);

// Node test harness for the protocol codecs (no browser APIs used).
import {
  Reader, Writer, varintSize, encodeStreamHeader, decodeStreamHeader,
  frameMessage, decodeDatagramHeader, encodeOpenReliable, encodeOpenUnreliable,
  encodeCloseUnreliable, decodeCtrlMessage, toHex, CtrlMsg,
} from '../src/protocol.js';

let pass = 0, fail = 0;
function check(name, got, want) {
  const ok = got === want;
  if (ok) pass++;
  else { fail++; console.log(`FAIL ${name}: got ${got} want ${want}`); }
}

// QUIC varint round trips at every boundary
for (const v of [0n, 1n, 62n, 63n, 64n, 16383n, 16384n, 1073741823n, 1073741824n, 4611686018427387903n]) {
  const w = new Writer().varint(v).toBytes();
  check(`varint size ${v}`, w.length, varintSize(v));
  check(`varint value ${v}`, new Reader(w).varint().value, v);
}
check('varint 2-byte prefix', new Writer().varint(64n).toBytes()[0] & 0xc0, 0x40);
check('varint 4-byte prefix', new Writer().varint(16384n).toBytes()[0] & 0xc0, 0x80);
check('varint 8-byte prefix', new Writer().varint(1073741824n).toBytes()[0] & 0xc0, 0xc0);

// zigzag signed varints
for (const v of [0n, 1n, -1n, 2n, -2n, 1000000n, -1000000n]) {
  const w = new Writer().svarint(v).toBytes();
  check(`svarint ${v}`, new Reader(w).svarint(), v);
}

// stream header
{
  const b = encodeStreamHeader(4, 0xdeadbeef);
  const d = decodeStreamHeader(b);
  check('stream magic', d.magic, 6);
  check('stream kind', d.kind, 1);
  check('stream app', d.appIndex, 4);
  check('stream chan', d.channelId, 0xdeadbeef);
}

// framing
{
  const payload = new Uint8Array([9, 8, 7]);
  const f = frameMessage(payload);
  const r = new Reader(f);
  check('frame len', Number(r.varint().value), 3);
  check('frame body', toHex(r.bytesN(3)), '09 08 07');
}

// control messages
{
  const d = decodeCtrlMessage(encodeOpenReliable(1, 2));
  check('openReliable type', d.type, CtrlMsg.OpenReliable);
  check('openReliable app', d.appIndex, 1);
  check('openReliable chan', d.channelId, 2);
}
{
  const d = decodeCtrlMessage(encodeOpenUnreliable(3, 4, 77));
  check('openUnreliable type', d.type, CtrlMsg.OpenUnreliable);
  check('openUnreliable wireId', d.wireId, 77);
}
{
  const d = decodeCtrlMessage(encodeCloseUnreliable(5, 1234n, 9n));
  check('close type', d.type, CtrlMsg.CloseUnreliable);
  check('close reason', d.reason, 5);
  check('close wireId', d.wireId, 1234n);
  check('close chan', d.channelId, 9n);
}

// datagram header
{
  const w = new Writer().svarint(-3).varint(7).varint(1000).varint(2).toBytes();
  const d = decodeDatagramHeader(w);
  check('dg channel', d.channelIdSigned, -3n);
  check('dg sendId', d.sendId, 7n);
  check('dg fragSize', d.fragSize, 1000n);
  check('dg frag', d.frag, 2n);
}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

