95: /** Parses an SSE body into a list of {event, data} records. */
96: export function parseSse(text) {
97:   const records = [];
98:   let cur = { event: 'message', data: [] };
99:   for (const rawLine of text.split(/\r?\n/)) {
100:     const line = rawLine;
101:     if (line === '') {
102:       if (cur.data.length || cur.event !== 'message') {
103:         records.push({ event: cur.event, data: cur.data.join('\n') });
104:       }
105:       cur = { event: 'message', data: [] };
106:       continue;
107:     }
108:     if (line.startsWith(':')) continue;
109:     const idx = line.indexOf(':');
110:     const field = idx === -1 ? line : line.slice(0, idx);
111:     let value = idx === -1 ? '' : line.slice(idx + 1);
112:     if (value.startsWith(' ')) value = value.slice(1);
113:     if (field === 'event') cur.event = value;
114:     else if (field === 'data') cur.data.push(value);
115:     else if (field === 'id' || field === 'retry') { /* bookkeeping */ }
116:   }
117:   if (cur.data.length || cur.event !== 'message') records.push({ event: cur.event, data: cur.data.join('\n') });
118:   return records;
119: }
