131:   if (!res.ok) {
132:     throw new RobloxApiError(`join-game v2 failed with HTTP ${res.status}`, { status: res.status, body: text.slice(0, 1000), url });
133:   }
134:   // Some deployments answer v2 with plain JSON rather than SSE.
135:   const trimmed = text.trim();
136:   if (trimmed.startsWith('{')) {
137:     let json;
138:     try { json = JSON.parse(trimmed); } catch (e) {
139:       throw new RobloxApiError('v2 join reply was neither JSON nor SSE', { status: res.status, body: text.slice(0, 500), url });
140:     }
141:     return { api: 'v2', status: res.status, reply: json, raw: text };
142:   }
143:   const events = parseSse(text);
144:   for (const ev of events) log(`  SSE event=${ev.event} data=${ev.data.slice(0, 200)}`);
145:   const ready = events.find(e => e.event === 'ResponseReady');
146:   let reply = null;
147:   if (ready && ready.data) {
148:     try { reply = JSON.parse(ready.data); } catch { /* tolerate */ }
149:   }
150:   if (!reply) {
151:     // Fall back to any event carrying JSON with a joinScript.
152:     for (const ev of events) {
153:       if (!ev.data) continue;
