348:     else if (typeof value === 'bigint') big = value;
349:     else if (typeof value === 'string') {
350:       const t = value.trim();
351:       if (t === '') return '0000000000000000';
352:       if (/^0x[0-9a-f]+$/i.test(t)) big = BigInt(t);
353:       else if (/^[0-9a-f]{16}$/i.test(t)) big = BigInt('0x' + t);
354:       else if (/^\d+$/.test(t)) big = BigInt(t);
355:       else if (/^[0-9a-f]+$/i.test(t)) big = BigInt('0x' + t);
356:       else throw new Error(`unrecognized caps format: ${t}`);
357:     } else throw new Error('unrecognized caps type: ' + typeof value);
358:     const hex = (big & 0xffffffffffffffffn).toString(16).padStart(16, '0');
359:     log(`capabilities = 0x${hex} (from ${JSON.stringify(value)})`);
360:     return hex;
361:   } catch (e) {
