367: export function normalizeCertHashes(value, log = () => {}) {
368:   if (value === undefined || value === null) return [];
369:   const list = Array.isArray(value) ? value : [value];
370:   const out = [];
371:   for (const item of list) {
372:     if (item == null) continue;
373:     if (item instanceof ArrayBuffer) { out.push(new Uint8Array(item)); continue; }
374:     if (ArrayBuffer.isView(item)) { out.push(new Uint8Array(item.buffer, item.byteOffset, item.byteLength)); continue; }
375:     if (typeof item !== 'string') continue;
376:     const t = item.trim();
377:     let bytes = null;
378:     if (/^[0-9a-f]{64}$/i.test(t)) bytes = hexToBytes(t);
379:     else if (/^[A-Za-z0-9+/]{43}=?$/.test(t)) bytes = base64ToBytes(t);
380:     if (bytes && bytes.length === 32) out.push(bytes);
381:   }
382:   log(`certHashes: ${out.length} SHA-256 digest(s)` + (out.length ? '' : ' (none usable; TLS pinning disabled)'));
