57: function selfTest() {
58:   const results = [];
59:   const eq = (name, a, b) => results.push({ name, ok: a === b, a, b });
60: 
61:   // varint round trip
62:   for (const v of [0n, 63n, 64n, 16383n, 16384n, 1073741823n, 1073741824n, 4611686018427387903n]) {
63:     const w = new Writer().varint(v).toBytes();
64:     const r = new Reader(w).varint();
65:     eq(`varint(${v})`, r.value, v);
66:   }
67:   // zigzag
68:   for (const v of [0n, 1n, -1n, 12345n, -12345n]) {
69:     const w = new Writer().svarint(v).toBytes();
70:     eq(`svarint(${v})`, new Reader(w).svarint(), v);
71:   }
72:   // stream header
73:   {
74:     const b = encodeStreamHeader(3, 0x11223344);
75:     const d = decodeStreamHeader(b);
76:     eq('stream header magic', d.magic, 0x06);
77:     eq('stream header app', d.appIndex, 3);
78:     eq('stream header chan', d.channelId, 0x11223344);
79:   }
80:   // ctrl messages
81:   {
82:     const d = decodeCtrlMessage(encodeOpenReliable(2, 5));
83:     eq('ctrl OpenReliable type', d.type, 1);
84:     eq('ctrl OpenReliable app', d.appIndex, 2);
85:     eq('ctrl OpenReliable chan', d.channelId, 5);
86:   }
87:   // datagram header
88:   {
89:     const w = new Writer().svarint(-7).varint(42).varint(0).toBytes();
90:     const d = decodeDatagramHeader(w);
91:     eq('datagram channel', d.channelIdSigned, -7n);
92:     eq('datagram sendId', d.sendId, 42n);
93:   }
94:   // framing
95:   {
96:     const payload = new Uint8Array([1, 2, 3, 4, 5]);
97:     const framed = frameMessage(payload);
98:     const r = new Reader(framed);
99:     eq('frame len', Number(r.varint().value), 5);
100:     eq('frame body', r.u32be === undefined ? 0 : 1, 1);
101:   }
102: 
103:   const failed = results.filter(r => !r.ok);
104:   for (const r of results) {
105:     if (!r.ok) log(`SELFTEST FAIL ${r.name}: got ${r.a} expected ${r.b}`);
106:   }
107:   if (!failed.length) {
108:     log(`SELFTEST OK: ${results.length} checks passed`);
109:     setStatus('codec self-test passed', 'ok');
110:   } else {
111:     setStatus(`${failed.length} self-test failures (see log)`, 'err');
112:   }
