import json
try:
    data = json.load(open('fflags.json'))
except Exception as e:
    print("load error:", e); raise SystemExit
# data may be nested; search keys containing PureQuic or Rupp
def walk(o, path=""):
    if isinstance(o, dict):
        for k, v in o.items():
            walk(v, path + "/" + str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o[:100000]):
            walk(v, path + "[%d]" % i)
    else:
        pass

hits = []
def find(o, prefix=""):
    if isinstance(o, dict):
        for k, v in o.items():
            if any(s in str(k) for s in ["PureQuic","Rupp","RTcIo","Rtcio","RtcIo"]):
                hits.append((prefix + "/" + str(k), v if not isinstance(v,(dict,list)) else type(v).__name__))
            find(v, prefix + "/" + str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            find(v, prefix + "[%d]" % i)
find(data)
for h in hits[:80]:
    print(h)
print("total hits:", len(hits))
EOF

