const r = await tools["chrome-devtools"].evaluate_script({
  pageId: 13,
  function: `async () => {
    const parseSse = (text) => {
      const rec = []; let cur = { event: 'message', data: [] };
      for (const raw of text.split(/\\r?\\n/)) {
        if (raw === '') { if (cur.data.length || cur.event !== 'message') rec.push(cur); cur = { event: 'message', data: [] }; continue; }
        const idx = raw.indexOf(':'); const f = idx === -1 ? raw : raw.slice(0, idx);
        let v = idx === -1 ? '' : raw.slice(idx + 1); if (v.startsWith(' ')) v = v.slice(1);
        if (f === 'event') cur.event = v; else if (f === 'data') cur.data.push(v);
      }
      return rec;
    };
    const joinOne = async (placeId, gameId) => {
      const res = await fetch('https://gamejoin.roblox.com/v2/join-game', {
        method: 'POST', credentials: 'include',
        headers: { 'Content-Type': 'application/json; charset=utf-8', Accept: 'text/event-stream' },
        body: JSON.stringify({ placeId, gameId, isTeleport: false, gameJoinAttemptId: crypto.randomUUID(), browserTrackerId: 0, playSessionId: crypto.randomUUID(), eventId: crypto.randomUUID(), launchData: '', joinAttemptOrigin: 'PlayButton' })
      });
      const text = await res.text();
      const evs = parseSse(text);
      const ready = evs.find(e => e.event === 'ResponseReady');
      const reply = ready ? JSON.parse(ready.data.join('\\n')) : null;
      if (!reply) return { placeId, error: 'no reply', head: text.slice(0, 300) };
      if (!reply.joinScript) return { placeId, status: reply.status, message: reply.message, statusData: reply.statusData };
      const js = reply.joinScript;
      return {
        placeId, status: reply.status,
        gameFqdn: js.GameFqdn ?? js.gameFqdn ?? null,
        rbxTransportConfig: js.RbxTransportConfig ?? null,
        netStackPort: js.NetStackPort, netStackConfig: js.NetStackConfig,
        udmux: js.UdmuxEndpoints, rccVersion: js.RccVersion,
        channel: js.ChannelName, dc: js.DataCenterId,
      };
    };
    return { hubRoot: await joinOne(5322549911, 1864051673) };
  }`
});
return r;

