cd /tmp/opencode && python3 - <<'EOF'
import re
pid = 409166
# Find the hex token from the live capture in mocktail's memory
needles = [
    bytes.fromhex("eb53afb40a5f6b6b5980bd5f917fbaf3"),  # client's first RUPP token
    b"NetStackTokenValue",
    b"TokenValue",
    b"NetStackPort",
]
try:
    maps = open(f"/proc/{pid}/maps").read().splitlines()
except Exception as e:
    print("maps error:", e); raise SystemExit
regions = []
for line in maps:
    m = re.match(r"([0-9a-f]+)-([0-9a-f]+) (\S+) .*?(/\S+)?$", line)
    if not m: continue
    start, end, perms = int(m.group(1),16), int(m.group(2),16), m.group(3)
    path = m.group(4) or ""
    if 'r' in perms and end - start <= 512*1024*1024:
        regions.append((start, end, perms, path))
print("regions:", len(regions))
found = {}
try:
    mem = open(f"/proc/{pid}/mem", "rb", buffering=0)
except Exception as e:
    print("mem open error:", e); raise SystemExit
for (start, end, perms, path) in regions:
    try:
        mem.seek(start)
        data = mem.read(end - start)
    except Exception:
        continue
    for n in needles:
        idx = data.find(n)
        if idx != -1 and n not in found:
            found[n] = (start + idx, data[max(0, idx-120):idx+260])
for n, (addr, ctx) in found.items():
    print("=== FOUND", n[:24], "at", hex(addr))
    try:
        print("   ctx:", ctx.decode('utf-8','replace')[:360].replace("\n"," "))
    except Exception:
        print("   ctx hex:", ctx.hex()[:200])
if not found:
    print("none found")
EOF

