async () => {
    const parseSse = (text) => {
      const rec = []; let cur = { event: 'message', data: [] };
      for (const raw of text.split(/\r?\n/)) {
        if (raw === '') { if (cur.data.length || cur.event !== 'message') rec.push(cur); cur = { event: 'message', data: [] }; continue; }
        const idx = raw.indexOf(':'); const f = idx === -1 ? raw : raw.slice(0, idx);
        let v = idx === -1 ? '' : raw.slice(idx + 1); if (v.startsWith(' ')) v = v.slice(1);
        if (f === 'event') cur.event = v; else if (f === 'data') cur.data.push(v);
      }
      return rec;
    };
    const res = await fetch('https://gamejoin.roblox.com/v2/join-game', {
      method: 'POST', credentials: 'include',
      headers: { 'Content-Type': 'application/json; charset=utf-8', Accept: 'text/event-stream' },
      body: JSON.stringify({ placeId: 1818, gameId: 13058, isTeleport: false, gameJoinAttemptId: crypto.randomUUID(), browserTrackerId: 0, playSessionId: crypto.randomUUID(), eventId: crypto.randomUUID(), launchData: '', joinAttemptOrigin: 'PlayButton' })
    });
    const text = await res.text();
    const evs = parseSse(text);
    const ready = evs.find(e => e.event === 'ResponseReady');
    const reply = ready ? JSON.parse(ready.data.join('\n')) : null;
    if (!reply || !reply.joinScript) return { error: 'no joinScript', status: reply && reply.status };
    const js = reply.joinScript;
    const cfg = JSON.parse(decodeURIComponent(js.NetStackConfig));
    const parts = (js.ClientTicket || '').split(';');
    return {
      at: Date.now(),
      udmuxIp: js.UdmuxEndpoints[0].Address, rccIp: js.ServerConnections[0].Address,
      netStackPort: js.NetStackPort, netStackTokenB64: js.NetStackTokenValue,
      caps: cfg.caps, ticketVersion: parts[parts.length - 1], ticketFields: [parts[2], parts[3]],
      gameId: js.GameId, placeId: js.PlaceId,
    };
  }

