#!/usr/bin/env python3
"""Decisive experiment: does the server open app=6 channels WITHOUT early-auth?

Connects (RUPP+QUIC), opens ctrl stream only, sends nothing else. Logs all
server-initiated streams/ctrl messages/datagrams for N seconds.
"""
import asyncio
import base64
import json
import socket
import ssl
import struct
import sys
import time

from aioquic.quic.configuration import QuicConfiguration
from aioquic.quic.connection import QuicConnection
from aioquic.quic.events import (HandshakeCompleted, ConnectionTerminated, ProtocolNegotiated,
                                 StreamDataReceived, StreamReset, DatagramFrameReceived)

CTX = {}


def make_rupp(payload, dst_ip, dst_port, token, subtype=1):
    tlv1 = bytes([1, 17, subtype]) + token
    tlv2 = bytes([2, 6]) + socket.inet_aton(dst_ip) + struct.pack('>H', dst_port)
    body = tlv1 + tlv2
    return bytes([1, 0]) + struct.pack('>H', 4 + len(body)) + body + payload


def parse_rupp(pkt):
    if len(pkt) < 4 or pkt[0] != 1:
        return None
    total = struct.unpack('>H', pkt[2:4])[0]
    return pkt[total:] if 4 <= total <= len(pkt) else None


def stream_header(app, chan):
    return bytes([0x06, 0x01, app]) + struct.pack('>I', chan)


def compact_varint(v):
    """Roblox compact u32 (2-bit tag)."""
    if v < 0x40:
        return bytes([v])                      # 00xxxxxx
    if v < 0x4000:
        return struct.pack('>H', 0x4000 | v)   # 01xxxxxx
    if v < 0x40000000:
        return struct.pack('>I', 0x80000000 | v)  # 10xxxxxx
    return struct.pack('>Q', 0xC000000000000000 | v)


def frame(payload):
    return compact_varint(len(payload)) + payload


async def main(join_path, seconds=25, do_auth=False, open_extra=None):
    js = json.load(open(join_path))
    cfg_json = json.loads(__import__('urllib.parse', fromlist=['unquote']).unquote(js["NetStackConfig"]))
    udmux_ip = js["UdmuxEndpoints"][0]["Address"]
    rcc_ip = js["ServerConnections"][0]["Address"]
    port = int(js["NetStackPort"])
    token = base64.b64decode(js["NetStackTokenValue"])

    cfg = QuicConfiguration(is_client=True, alpn_protocols=["RbxTransport"])
    cfg.verify_mode = ssl.CERT_NONE
    cfg.max_datagram_frame_size = 65535
    cfg.idle_timeout = 30.0
    conn = QuicConnection(configuration=cfg)
    peer = (udmux_ip, port)

    loop = asyncio.get_event_loop()
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.bind(("0.0.0.0", 0))
    sock.setblocking(False)

    live = [True]
    timer = [None]
    opened = {}

    def next_sid():
        return conn.get_next_available_stream_id()

    def open_stream(app, chan, label=""):
        sid = next_sid()
        conn.send_stream_data(sid, stream_header(app, chan))
        opened[sid] = (app, chan)
        print(f"  -> open stream {sid} app={app} chan={chan} {label}", flush=True)
        return sid

    def pump():
        if not live[0]:
            return
        now = time.monotonic()
        try:
            for data, addr in conn.datagrams_to_send(now):
                sock.sendto(make_rupp(data, rcc_ip, port, token, 1), peer)
        except OSError:
            return
        t = conn.get_timer()
        if t is not None:
            if timer[0]:
                timer[0].cancel()
            timer[0] = loop.call_later(max(0.0, t - now), lambda: (conn.handle_timer(time.monotonic()), pump(), None)[1])

    def on_readable():
        while True:
            try:
                data, addr = sock.recvfrom(65535)
            except (BlockingIOError, OSError):
                break
            p = parse_rupp(data)
            if p is None:
                continue
            conn.receive_datagram(p, peer, time.monotonic())
        while True:
            ev = conn.next_event()
            if ev is None:
                break
            handle(ev)
        pump()

    def handle(ev):
        if isinstance(ev, HandshakeCompleted):
            print("*** handshake complete ***", flush=True)
            ctrl = open_stream(0, 0, "(ctrl)")
            # Note: we do NOT send OpenReliable either; truly silent client.
            global ctrl_sid
            ctrl_sid = ctrl
            # start QUIC keepalive
            async def ping():
                while live[0]:
                    try:
                        conn.ping(None)
                    except Exception:
                        pass
                    await asyncio.sleep(1.0)
            asyncio.ensure_future(ping())
        elif isinstance(ev, ProtocolNegotiated):
            print("ALPN:", ev.alpn_protocol, flush=True)
        elif isinstance(ev, StreamDataReceived):
            st = opened.get(ev.stream_id, "server")
            print(f"  <<< stream {ev.stream_id} {st} {len(ev.data)}B: {ev.data[:48].hex()}", flush=True)
        elif isinstance(ev, DatagramFrameReceived):
            print(f"  <<< datagram {len(ev.data)}B: {ev.data[:48].hex()}", flush=True)
        elif isinstance(ev, ConnectionTerminated):
            print(f"*** terminated: code={ev.error_code} reason={ev.reason_phrase!r} ***", flush=True)
            live[0] = False
        elif isinstance(ev, StreamReset):
            print(f"  <<< StreamReset {ev.stream_id} err={ev.error_code}", flush=True)

    loop.add_reader(sock.fileno(), on_readable)
    conn.connect(peer, time.monotonic())
    pump()
    await asyncio.sleep(seconds)
    live[0] = False
    print("done", flush=True)


if __name__ == "__main__":
    jp = sys.argv[1]
    secs = int(sys.argv[2]) if len(sys.argv) > 2 else 25
    asyncio.run(main(jp, secs))

