#!/usr/bin/env python3
"""Decrypt native RbxTransport QUIC capture using SSLKEYLOGFILE.

Handles: RUPP strip, Initial decrypt (per-packet DCID incl. Retry), ClientHello
random matching, short-header decryption, stream+datagram reassembly.
"""
import struct
import sys
import hashlib
import hmac
from collections import defaultdict

sys.path.insert(0, "/tmp/opencode")
from quic_decrypt import parse_pcapng, extract_udp, load_keylog, try_ciphers, parse_varint
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDFExpand

QUIC_V1_SALT = bytes.fromhex("38762cf7f55934b34d179ae6a4c80cadccbb7f0a")


def hkdf_extract(salt, ikm):
    return hmac.new(salt, ikm, hashlib.sha256).digest()


def hkdf_expand_label(secret, label, ctx, length):
    full = b"tls13 " + label
    info = struct.pack(">H", length) + bytes([len(full)]) + full + bytes([len(ctx)]) + ctx
    return HKDFExpand(algorithm=hashlib.sha256(), length=length, info=info).derive(secret)


class Keys:
    def __init__(self, key, iv, hp):
        self.key, self.iv, self.hp = key, iv, hp
        self._hp = Cipher(algorithms.AES(self.hp), modes.ECB())
    def mask(self, sample):
        e = self._hp.encryptor()
        return e.update(sample) + e.finalize()
    def aead(self):
        return AESGCM(self.key)


def initial_keys(dcid):
    sec = hkdf_extract(QUIC_V1_SALT, dcid)
    out = []
    for lbl in (b"client in", b"server in"):
        s = hkdf_expand_label(sec, lbl, b"", 32)
        out.append(Keys(
            hkdf_expand_label(s, b"quic key", b"", 16),
            hkdf_expand_label(s, b"quic iv", b"", 12),
            hkdf_expand_label(s, b"quic hp", b"", 16)))
    return out


def decrypt_initial(pkt, keys):
    if not pkt or not (pkt[0] & 0x80) or ((pkt[0] >> 4) & 3) != 0:
        return None
    pos = 5
    dcil = pkt[pos]; pos += 1
    pos += dcil
    scil = pkt[pos]; pos += 1
    scid = pkt[pos:pos+scil]; pos += scil
    tl, p2 = parse_varint(pkt, pos)
    pos = p2 + tl
    plen, p3 = parse_varint(pkt, pos)
    pn_off = p3
    if pn_off + 4 + 16 > len(pkt):
        return None
    sample = pkt[pn_off+4: pn_off+20]
    mask = keys.mask(sample)
    first = pkt[0] ^ (mask[0] & 0x0F)
    pn_len = (first & 3) + 1
    pn_bytes = bytes(pkt[pn_off+i] ^ mask[1+i] for i in range(pn_len))
    pn = int.from_bytes(pn_bytes, "big")
    header = bytes([first]) + bytes(pkt[1:pn_off]) + pn_bytes
    end = min(len(pkt), pn_off + plen)
    ct = bytes(pkt[pn_off+pn_len:end])
    nonce = (int.from_bytes(keys.iv, "big") ^ pn).to_bytes(12, "big")
    try:
        return pn, AESGCM(keys.key).decrypt(nonce, ct, header)
    except Exception:
        return None


def parse_frames(plain, acc):
    """acc: dict with crypto list, streams dict, datagrams list."""
    off = 0
    while off < len(plain):
        t = plain[off]; off += 1
        if t == 0x00:
            continue
        if t == 0x01:
            acc["ping"] += 1
            continue
        if t in (0x02, 0x03):
            _, off = parse_varint(plain, off)
            _, off = parse_varint(plain, off)
            cnt, off = parse_varint(plain, off)
            _, off = parse_varint(plain, off)
            for _ in range(cnt):
                _, off = parse_varint(plain, off)
            if t == 0x03:
                for _ in range(3):
                    _, off = parse_varint(plain, off)
            continue
        if t == 0x06:
            coff, off = parse_varint(plain, off)
            ln, off = parse_varint(plain, off)
            acc["crypto"].append((coff, plain[off:off+ln]))
            off += ln
            continue
        if 0x08 <= t <= 0x0F:
            sid, off = parse_varint(plain, off)
            offset = 0
            if t & 0x04:
                offset, off = parse_varint(plain, off)
            if t & 0x02:
                ln, off = parse_varint(plain, off)
            else:
                ln = len(plain) - off
            data = plain[off:off+ln]
            off += ln
            st = acc["streams"][sid]
            st.append((offset, data, bool(t & 0x01), bool(t & 0x02)))
            continue
        if t == 0x10:
            _, off = parse_varint(plain, off)
            continue
        if t == 0x11:
            _, off = parse_varint(plain, off)
            _, off = parse_varint(plain, off)
            continue
        if 0x12 <= t <= 0x17:
            if t in (0x13, 0x14, 0x15, 0x16, 0x17):
                _, off = parse_varint(plain, off)
            continue
        if t == 0x18:
            _, off = parse_varint(plain, off)
            _, off = parse_varint(plain, off)
            ln = plain[off]; off += 1 + ln + 16
            continue
        if t == 0x19:
            _, off = parse_varint(plain, off)
            continue
        if t in (0x1A, 0x1B):
            off += 8
            continue
        if t in (0x1C, 0x1D):
            acc["closed"] = True
            break
        if t == 0x1E:
            continue
        if t == 0x30:
            acc["datagrams"].append(plain[off:])
            off = len(plain)
            continue
        if t == 0x31:
            ln, off = parse_varint(plain, off)
            acc["datagrams"].append(plain[off:off+ln])
            off += ln
            continue
        if t == 0x1F:
            break
        break


def strip_rupp(p):
    if len(p) >= 4 and p[0] == 1 and p[1] == 0:
        total = struct.unpack('>H', p[2:4])[0]
        if 4 <= total <= len(p):
            return p[total:]
    return p


def find_client_hello(crypto_chunks):
    """Reassemble crypto and find ClientHello random (32B)."""
    chunks = sorted(crypto_chunks)
    blob = bytearray()
    for off, data in chunks:
        if off == len(blob):
            blob.extend(data)
        elif off < len(blob) < off + len(data):
            blob.extend(data[len(blob)-off:])
    b = bytes(blob)
    # find handshake ClientHello: type 1, length 3B, version 2B (0303), random 32B
    for i in range(0, min(len(b)-44, 512)):
        if b[i] == 0x01 and b[i+1] == 0x00:
            ln = int.from_bytes(b[i+1:i+4], "big")
            if 30 <= ln <= 2000 and i + 4 + ln <= len(b) + 200:
                if b[i+4:i+6] == b"\x03\x03":
                    return b[i+6:i+38], b
    return None, b


def main():
    pcap = sys.argv[1] if len(sys.argv) > 1 else "/tmp/opencode/native_rbxt4.pcapng"
    keylog = sys.argv[2] if len(sys.argv) > 2 else "/tmp/opencode/native_keys.log"
    entries = load_keylog(keylog)
    linktype, pkts = parse_pcapng(pcap)

    flows = defaultdict(list)
    for ts, p in pkts:
        r = extract_udp(p, linktype)
        if not r:
            continue
        src, sp, dst, dp, payload = r
        flows[(src, sp, dst, dp)].append((ts, strip_rupp(payload)))

    print(f"linktype={linktype} pkts={len(pkts)} flows={len(flows)}")

    # Identify QUIC flows, use first Initial's DCID -> find the goal connection.
    for flow, pls in sorted(flows.items(), key=lambda kv: -len(kv[1])):
        src, sp, dst, dp = flow
        raw = [p for ts, p in pls if p]
        if not raw:
            continue
        # Decrypt Initials with per-packet DCID-derived keys
        acc = {"crypto": [], "streams": defaultdict(list), "datagrams": [], "ping": 0, "closed": False}
        initial_ok = 0
        for p in raw:
            if p and (p[0] & 0x80) and ((p[0] >> 4) & 3) == 0:
                if len(p) < 7:
                    continue
                dcil = p[5]
                if 6 + dcil > len(p):
                    continue
                dcid = p[6:6+dcil]
                (ck, sk) = initial_keys(dcid)
                r = decrypt_initial(p, ck)
                if not r:
                    r = decrypt_initial(p, sk)
                if r:
                    initial_ok += 1
                    parse_frames(r[1], acc)
        rev = (dst, dp, src, sp)
        for ts, p in flows.get(rev, []):
            if p and (p[0] & 0x80) and ((p[0] >> 4) & 3) == 0 and len(p) >= 7:
                dcil = p[5]
                if 6 + dcil > len(p):
                    continue
                dcid = p[6:6+dcil]
                (ck, sk) = initial_keys(dcid)
                r = decrypt_initial(p, sk)
                if not r:
                    r = decrypt_initial(p, ck)
                if r:
                    initial_ok += 1
                    parse_frames(r[1], acc)

        if initial_ok == 0:
            continue
        random, blob = find_client_hello(acc["crypto"])
        tag = random.hex() if random else "NO-CH"
        has_keys = random and random.hex() in entries
        print(f"\n=== {src}:{sp}->{dst}:{dp} pkts={len(raw)} initials_ok={initial_ok} ch={tag[:24]} keylog={'YES' if has_keys else 'no'}")
        if not has_keys:
            if random:
                # print a few candidate randoms from keylog for debugging
                ks = list(entries.keys())
                print(f"    keylog has {len(ks)} randoms; sample {ks[:2]}")
            continue

        secs = entries[random.hex()]

        # now decrypt short-header packets of this flow (and reverse) with
        # client/server traffic secrets
        def decrypt_short_dir(pkt, keys, dcid_len):
            if not pkt or (pkt[0] & 0x80):
                return None
            if len(pkt) < 1 + dcid_len + 4 + 16:
                return None
            pn_off = 1 + dcid_len
            sample = pkt[pn_off+4: pn_off+20]
            mask = keys.mask(sample)
            kfirst = pkt[0] ^ (mask[0] & 0x1F)
            pn_len = (kfirst & 3) + 1
            if pn_off + pn_len > len(pkt):
                return None
            pn_bytes = bytes(pkt[pn_off+i] ^ mask[1+i] for i in range(pn_len))
            pn = int.from_bytes(pn_bytes, "big")
            header = bytes([kfirst]) + bytes(pkt[1:pn_off]) + pn_bytes
            ct = bytes(pkt[pn_off+pn_len:])
            nonce = (int.from_bytes(keys.iv, "big") ^ pn).to_bytes(12, "big")
            try:
                return pn, AESGCM(keys.key).decrypt(nonce, ct, header)
            except Exception:
                return None

        def best_keys(secret):
            for klen, aead in ((16, AESGCM), (32, AESGCM)):
                for halg in (hashlib.sha256(), hashlib.sha384()):
                    try:
                        key = hkdf_expand_label(secret, b"quic key", b"", klen)
                        iv = hkdf_expand_label(secret, b"quic iv", b"", 12)
                        hp = hkdf_expand_label(secret, b"quic hp", b"", klen)
                        yield Keys(key, iv, hp)
                    except Exception:
                        pass

        # cipher suite: ngtcp2 with this build likely AES-128-GCM; try both
        csec = secs["CLIENT_TRAFFIC_SECRET_0"]
        ssec = secs["SERVER_TRAFFIC_SECRET_0"]
        results = {}
        for name, sec in (("client", csec), ("server", ssec)):
            for keys in best_keys(sec):
                # try dcid lens 20, 8, 0
                for dl in (20, 8, 0):
                    ok = 0
                    for ts, p in ([(ts, p) for ts, p in pls]):
                        if p and not (p[0] & 0x80):
                            if decrypt_short_dir(p, keys, dl):
                                ok += 1
                    if ok:
                        results[(name, dl, id(keys))] = (keys, dl, name, ok)
        if not results:
            print("    short-header decrypt: FAILED")
            continue

        # pick best per direction
        best = {}
        for (name, dl, kid), (keys, dl2, nm, ok) in sorted(results.items(), key=lambda kv: -kv[1][3]):
            if name not in best:
                best[name] = (keys, dl, ok)
        print(f"    short-header decrypt: {[(k, v[2]) for k, v in best.items()]}")

        # decrypt everything
        acc2 = {"crypto": [], "streams": defaultdict(list), "datagrams": [], "ping": 0, "closed": False}
        for ts, p in pls:
            if not p or (p[0] & 0x80):
                continue
            keys, dl, _ = best["client"]
            r = decrypt_short_dir(p, keys, dl)
            if r:
                parse_frames(r[1], acc2)
        for ts, p in flows.get(rev, []):
            if not p or (p[0] & 0x80):
                continue
            keys, dl, _ = best["server"]
            r = decrypt_short_dir(p, keys, dl)
            if r:
                parse_frames(r[1], acc2)

        print(f"    client streams: {len(acc2['streams'])} datagrams: {len(acc2['datagrams'])} ping={acc2['ping']}")
        for sid, chunks in sorted(acc2["streams"].items()):
            merged = bytearray()
            for off, data, fin, _ln in sorted(chunks):
                if off == len(merged):
                    merged.extend(data)
                elif off < len(merged) < off + len(data):
                    merged.extend(data[len(merged)-off:])
            print(f"    stream {sid}: {len(merged)}B head={bytes(merged[:64]).hex()}")
        for i, d in enumerate(acc2["datagrams"][:30]):
            print(f"    dgram[{i}] {len(d)}B: {d[:64].hex()}")


if __name__ == "__main__":
    main()

