#!/usr/bin/env python3
"""Extract ClientHello randoms from all QUIC flows and match against keylog."""
import struct
import sys
from collections import defaultdict

sys.path.insert(0, "/tmp/opencode")
from quic_full import initial_keys, decrypt_initial, parse_frames, strip_rupp
from quic_decrypt import parse_pcapng, extract_udp, load_keylog


def main():
    pcap = sys.argv[1] if len(sys.argv) > 1 else "/tmp/opencode/native_rbxt4.pcapng"
    keylog = sys.argv[2] if len(sys.argv) > 2 else "/tmp/opencode/native_keys.log"
    entries = load_keylog(keylog)
    print("keylog randoms:", len(entries))

    linktype, pkts = parse_pcapng(pcap)
    flows = defaultdict(list)
    for ts, p in pkts:
        r = extract_udp(p, linktype)
        if not r:
            continue
        src, sp, dst, dp, payload = r
        flows[(src, sp, dst, dp)].append((ts, strip_rupp(payload)))

    # For each flow collect crypto from Initials (client && server)
    def get_ch(crypto):
        chunks = sorted(crypto)
        blob = bytearray()
        for off, data in chunks:
            if off == len(blob):
                blob.extend(data)
            elif off < len(blob) < off + len(data):
                blob.extend(data[len(blob)-off:])
        b = bytes(blob)
        for i in range(0, min(len(b) - 40, 400)):
            if b[i] == 1 and b[i+1] == 0 and b[i+4:i+6] == b"\x03\x03":
                ln = int.from_bytes(b[i+1:i+4], "big")
                if 30 <= ln <= 3000:
                    return b[i+6:i+38].hex(), b
        return None, b

    for flow, pls in sorted(flows.items(), key=lambda kv: -len(kv[1])):
        src, sp, dst, dp = flow
        crypto = []
        chassis = []
        for ts, p in pls:
            if p and (p[0] & 0x80) and ((p[0] >> 4) & 3) == 0 and len(p) >= 7:
                dcil = p[5]
                if 6 + dcil > len(p):
                    continue
                dcid = p[6:6+dcil]
                ck, sk = initial_keys(dcid)
                r = decrypt_initial(p, ck) or decrypt_initial(p, sk)
                if r:
                    parse_frames(r[1], {"crypto": crypto, "streams": {}, "datagrams": [], "ping": 0})
        rev = (dst, dp, src, sp)
        for ts, p in flows.get(rev, []):
            if p and (p[0] & 0x80) and ((p[0] >> 4) & 3) == 0 and len(p) >= 7:
                dcil = p[5]
                if 6 + dcil > len(p):
                    continue
                dcid = p[6:6+dcil]
                ck, sk = initial_keys(dcid)
                r = decrypt_initial(p, sk) or decrypt_initial(p, ck)
                if r:
                    parse_frames(r[1], {"crypto": crypto, "streams": {}, "datagrams": [], "ping": 0})
        if not crypto:
            continue
        rnd, blob = get_ch(crypto)
        if not rnd:
            print(f"flow {src}:{sp}->{dst}:{dp} pkts={len(pls)} NO-CH blob={len(blob)}")
            continue
        hit = rnd in entries
        print(f"flow {src}:{sp}->{dst}:{dp} pkts={len(pls)} ch={rnd} keylog={'MATCH' if hit else '-'}")
        if hit:
            print("   labels:", list(entries[rnd].keys()))


if __name__ == "__main__":
    main()

